    Differential Revision: https://phabricator.services.mozilla.com/D231274

diff --git a/mail/components/inappnotifications/content/in-app-notification.mjs b/mail/components/inappnotifications/content/in-app-notification.mjs
index 861ecea11e7..48c6e883c50 100644
--- a/mail/components/inappnotifications/content/in-app-notification.mjs
+++ b/mail/components/inappnotifications/content/in-app-notification.mjs
@@ -69,6 +69,16 @@ class InAppNotification extends HTMLElement {
     for (const [key, value] of Object.entries(attributes)) {
       this.#container.setAttribute(value, notification[key]);
     }
+
+    const positions = ["bottom-spaces-toolbar", "bottom-today-pane"];
+
+    for (const position of positions) {
+      this.classList.toggle(position, notification.position === position);
+    }
+
+    if (!positions.includes(notification.position)) {
+      this.classList.add("bottom-spaces-toolbar");
+    }
   }
 }

